#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct ModulePathFileRow {
    pub module_path: NonEmptyStr,
    pub file_path: FilePath,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum ModulePathFileIndexRefusal {
    ModulePathFileDuplicateSame {
        module_path: NonEmptyStr,
        file_path: FilePath,
    },
    ModulePathFileConflict {
        module_path: NonEmptyStr,
        first_file: FilePath,
        second_file: FilePath,
    },
}
impl ModulePathFileIndexRefusal {
    pub fn module_path(&self) -> NonEmptyStr {
        match self {
            ModulePathFileIndexRefusal::ModulePathFileDuplicateSame {
                module_path: __val, ..
            } => __val.clone(),
            ModulePathFileIndexRefusal::ModulePathFileConflict {
                module_path: __val, ..
            } => __val.clone(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct ModulePathFileIndexBuild {
    pub entries: Rc<HashMap<String, FilePath>>,
    pub refusal: Option<Rc<ModulePathFileIndexRefusal>>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum ModulePathFileIndex {
    ModulePathFileIndexReady {
        entries: Rc<HashMap<String, FilePath>>,
    },
    ModulePathFileIndexRefused {
        refusal: Rc<ModulePathFileIndexRefusal>,
    },
}

pub fn module_path_file_index_fold_step(
    build: Rc<ModulePathFileIndexBuild>,
    row: Rc<ModulePathFileRow>,
) -> Rc<ModulePathFileIndexBuild> {
    match build.refusal.clone() {
        Some(_) => build.clone(),
        None => {
            let key = row.module_path.clone();
            match v1_rt::map_get(&build.entries.clone(), key.clone()) {
                None => Rc::new(ModulePathFileIndexBuild {
                    entries: v1_rt::rc_map_insert(
                        build.entries.clone(),
                        key.clone(),
                        row.file_path.clone(),
                    ),
                    refusal: None,
                }),
                Some(existing) => {
                    if (existing.clone() == row.file_path.clone()) {
                        Rc::new(ModulePathFileIndexBuild {
                            entries: build.entries.clone(),
                            refusal: Some(Rc::new(
                                ModulePathFileIndexRefusal::ModulePathFileDuplicateSame {
                                    module_path: row.module_path.clone(),
                                    file_path: row.file_path.clone(),
                                },
                            )),
                        })
                    } else {
                        Rc::new(ModulePathFileIndexBuild {
                            entries: build.entries.clone(),
                            refusal: Some(Rc::new(
                                ModulePathFileIndexRefusal::ModulePathFileConflict {
                                    module_path: row.module_path.clone(),
                                    first_file: existing.clone(),
                                    second_file: row.file_path.clone(),
                                },
                            )),
                        })
                    }
                }
            }
        }
    }
}

pub fn module_path_file_index_from_rows(
    rows: Rc<Vec<Rc<ModulePathFileRow>>>,
) -> Rc<ModulePathFileIndex> {
    {
        let build = rows.clone().iter().cloned().fold(
            Rc::new(ModulePathFileIndexBuild {
                entries: v1_rt::rc_empty_map::<String, String>(),
                refusal: None,
            }),
            |acc: Rc<ModulePathFileIndexBuild>, row: Rc<ModulePathFileRow>| {
                module_path_file_index_fold_step(acc, row.clone())
            },
        );
        match build.refusal.clone() {
            Some(refusal) => Rc::new(ModulePathFileIndex::ModulePathFileIndexRefused {
                refusal: refusal.clone(),
            }),
            None => Rc::new(ModulePathFileIndex::ModulePathFileIndexReady {
                entries: build.entries.clone(),
            }),
        }
    }
}

