#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CrossFileBindingProvenanceBuild {
    pub module_files: Rc<HashMap<String, FilePath>>,
    pub provenances_reversed: Rc<Vec<Rc<CrossFileBindingProvenance>>>,
    pub first_failure: Option<Rc<CrossFileBindingProvenanceProjection>>,
    pub more_failures_reversed: Rc<Vec<Rc<CrossFileBindingProvenanceProjection>>>,
}

pub fn cross_file_binding_provenance_fold_step(
    acc: Rc<CrossFileBindingProvenanceBuild>,
    provider: Rc<BoundReferenceProvider>,
) -> Rc<CrossFileBindingProvenanceBuild> {
    {
        let projection =
            cross_file_binding_provenance_from_provider(provider.clone(), acc.module_files.clone());
        match (*projection.clone()).clone() {
    CrossFileBindingProvenanceProjection::CrossFileBindingProvenanceProjectionBound { provenance: provenance, .. } => Rc::new(CrossFileBindingProvenanceBuild {
    module_files: acc.module_files.clone(),
    provenances_reversed: v1_rt::concat(Rc::new(vec![provenance.clone()]), acc.provenances_reversed.clone()),
    first_failure: acc.first_failure.clone(),
    more_failures_reversed: acc.more_failures_reversed.clone(),
}),
    CrossFileBindingProvenanceProjection::CrossFileBindingProvenanceProjectionFilePathMissing { module_path: _, .. } => match acc.first_failure.clone() {
    None => Rc::new(CrossFileBindingProvenanceBuild {
    module_files: acc.module_files.clone(),
    provenances_reversed: acc.provenances_reversed.clone(),
    first_failure: Some(projection.clone()),
    more_failures_reversed: acc.more_failures_reversed.clone(),
}),
    Some(_) => Rc::new(CrossFileBindingProvenanceBuild {
    module_files: acc.module_files.clone(),
    provenances_reversed: acc.provenances_reversed.clone(),
    first_failure: acc.first_failure.clone(),
    more_failures_reversed: v1_rt::concat(Rc::new(vec![projection.clone()]), acc.more_failures_reversed.clone()),
}),
},
}
    }
}

pub fn cross_file_binding_provenance_from_bound_population(
    population: Rc<BoundReferencePopulation>,
    module_files: Rc<HashMap<String, String>>,
) -> Rc<CrossFileBindingProvenancePopulation> {
    match (*population.clone()).clone() {
        BoundReferencePopulation::ReferencePopulationRefused { .. } => Rc::new(
            CrossFileBindingProvenancePopulation::CrossFileBindingPopulationBindingRefused {
                population: population.clone(),
            },
        ),
        BoundReferencePopulation::AllReferencesBound {
            providers: providers,
            ..
        } => {
            let build = providers.clone().iter().cloned().fold(
                Rc::new(CrossFileBindingProvenanceBuild {
                    module_files: module_files.clone(),
                    provenances_reversed: Rc::new(vec![]),
                    first_failure: None,
                    more_failures_reversed: Rc::new(vec![]),
                }),
                |acc: Rc<CrossFileBindingProvenanceBuild>, provider: Rc<BoundReferenceProvider>| {
                    cross_file_binding_provenance_fold_step(acc, provider.clone())
                },
            );
            match build.first_failure.clone() {
                None => Rc::new(
                    CrossFileBindingProvenancePopulation::AllCrossFileBindingsBound {
                        provenances: v1_rt::reverse(build.provenances_reversed.clone()),
                    },
                ),
                Some(first_failure) => Rc::new(
                    CrossFileBindingProvenancePopulation::CrossFileBindingPopulationRefused {
                        first_failure: first_failure.clone(),
                        more_failures: v1_rt::reverse(build.more_failures_reversed.clone()),
                    },
                ),
            }
        }
    }
}

