pub fn reference_derived_dependency_projection_for_assembled_closure(
    closure: Rc<AssembledCrossFileBindingClosure>,
) -> Rc<AssembledClosureDependencyProjection> {
    match (*closure.clone()).clone() {
    AssembledCrossFileBindingClosure::AssembledCrossFileBindingClosureRefused { refusal: refusal, .. } => Rc::new(AssembledClosureDependencyProjection::AssembledClosureDependencyProjectionRefused {
    refusal: Rc::new(AssembledClosureDependencyProjectionRefusal::AssembledClosureDependencyProjectionModulePathFileRefused {
    refusal: match (*refusal.clone()).clone() {
    AssembledCrossFileBindingClosureRefusal::AssembledCrossFileBindingClosureModulePathFileRefused { refusal: module_refusal, .. } => module_refusal.clone(),
},
}),
}),
    AssembledCrossFileBindingClosure::AssembledCrossFileBindingClosureReady { transport, inputs, module_files: module_file_rows, .. } => match (*module_path_file_index_from_rows(module_file_rows.clone())).clone() {
    ModulePathFileIndex::ModulePathFileIndexRefused { refusal: refusal, .. } => Rc::new(AssembledClosureDependencyProjection::AssembledClosureDependencyProjectionRefused {
    refusal: Rc::new(AssembledClosureDependencyProjectionRefusal::AssembledClosureDependencyProjectionModulePathFileRefused {
    refusal: refusal.clone(),
}),
}),
    ModulePathFileIndex::ModulePathFileIndexReady { entries: module_files, .. } => match (*structural_binding_walk_selected_references(transport.clone(), inputs.clone(), reference_derived_dependency_binding_references(transport.references.clone()))).clone() {
    StructuralBindingWalk::StructuralBindingWalkReady { population: population, .. } => match (*reference_derived_dependency_projection(population.clone(), module_files.clone())).clone() {
    ReferenceDerivedDependencyProjection::ReferenceDerivedDependencyProjectionReady { binding_provenance, file_dependencies, bound_population, .. } => Rc::new(AssembledClosureDependencyProjection::AssembledClosureDependencyProjectionReady {
    projection: Rc::new(ReferenceDerivedDependencyProjection::ReferenceDerivedDependencyProjectionReady {
    binding_provenance: binding_provenance.clone(),
    file_dependencies: file_dependencies.clone(),
    bound_population: bound_population.clone(),
}),
}),
    ReferenceDerivedDependencyProjection::ReferenceDerivedDependencyProjectionBindingRefused { population: refused_population, .. } => Rc::new(AssembledClosureDependencyProjection::AssembledClosureDependencyProjectionRefused {
    refusal: Rc::new(AssembledClosureDependencyProjectionRefusal::AssembledClosureDependencyProjectionBindingRefused {
    population: refused_population.clone(),
}),
}),
    ReferenceDerivedDependencyProjection::ReferenceDerivedDependencyProjectionFileRefused { first_failure, more_failures, .. } => Rc::new(AssembledClosureDependencyProjection::AssembledClosureDependencyProjectionRefused {
    refusal: Rc::new(AssembledClosureDependencyProjectionRefusal::AssembledClosureDependencyProjectionFileRefused {
    first_failure: first_failure.clone(),
    more_failures: more_failures.clone(),
}),
}),
},
    StructuralBindingWalk::StructuralBindingWalkRefused { refusal: refusal, .. } => Rc::new(AssembledClosureDependencyProjection::AssembledClosureDependencyProjectionRefused {
    refusal: Rc::new(AssembledClosureDependencyProjectionRefusal::AssembledClosureDependencyProjectionStructuralRefused {
    refusal: refusal.clone(),
}),
}),
},
},
}
}

